uniform float radius : hint_range(0.0, 0.8) = 0.0;

void fragment() {
	if (distance(UV, vec2(0.5)) > radius) {
		discard;
	}
	COLOR = texture(TEXTURE, UV);
}

func _ready():
	$Sprite.material.set_shader_parameter("radius", 0.0)

func _unhandled_key_input(event):
	if event.pressed:
		var tween := create_tween()
		tween.tween_property($Sprite.material, "shader_parameter/radius", 0.8, 1.5)
